//! Typed IDs. Every ID is a UUID v7, generated by the caller: the domain has no clock and
//! no randomness. Wrappers keep a bare `Uuid` out of every signature.

use std::fmt;

use uuid::Uuid;

/// Why a value is not a valid ID.
#[derive(Debug, Clone, Copy, PartialEq, Eq, thiserror::Error)]
pub enum IdError {
    #[error("not a UUID")]
    Malformed,
    #[error("not a UUID v7")]
    NotV7,
}

macro_rules! uuid_v7_id {
    ($(#[$doc:meta])* $name:ident) => {
        $(#[$doc])*
        #[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
        pub struct $name(Uuid);

        impl $name {
            /// Wraps `uuid` if it is a version 7 UUID.
            pub fn from_uuid(uuid: Uuid) -> Result<Self, IdError> {
                if uuid.get_version_num() == 7 {
                    Ok(Self(uuid))
                } else {
                    Err(IdError::NotV7)
                }
            }

            /// Parses the text form (any case, surrounding whitespace ignored).
            pub fn parse(raw: &str) -> Result<Self, IdError> {
                Uuid::try_parse(raw.trim())
                    .map_err(|_| IdError::Malformed)
                    .and_then(Self::from_uuid)
            }

            #[must_use]
            pub fn as_uuid(&self) -> Uuid {
                self.0
            }
        }

        impl fmt::Display for $name {
            fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
                self.0.hyphenated().fmt(f)
            }
        }
    };
}

uuid_v7_id!(
    /// Identifies an agent.
    AgentId
);
uuid_v7_id!(
    /// Identifies an audit event.
    AuditEventId
);
